def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007

    if n == 0:
        return 1

    # Remove duplicates
    banned = list(set(banned))
    # If any banned string is empty, no valid string exists (though constraints say non-empty)
    if any(s == "" for s in banned):
        return 0

    # Build Aho-Corasick automaton
    # Each node: children dict, fail link, is_banned flag
    trie = [{}]  # trie[u][c] = next_node
    fail = [0]
    is_banned = [False]

    for word in banned:
        curr = 0
        for c in word:
            if c not in trie[curr]:
                trie[curr][c] = len(trie)
                trie.append({})
                fail.append(0)
                is_banned.append(False)
            curr = trie[curr][c]
        is_banned[curr] = True

    # BFS to build failure links and propagate is_banned
    from collections import deque
    queue = deque()

    for c in alphabet:
        if c in trie[0]:
            nxt = trie[0][c]
            fail[nxt] = 0
            queue.append(nxt)

    while queue:
        curr = queue.popleft()
        if is_banned[fail[curr]]:
            is_banned[curr] = True

        for c, nxt in trie[curr].items():
            f = fail[curr]
            while f > 0 and c not in trie[f]:
                f = fail[f]
            if f == 0 and c not in trie[0]:
                fail[nxt] = 0
            else:
                fail[nxt] = trie[f][c]
            queue.append(nxt)

    # Filter out unreachable or banned states to reduce matrix size
    num_nodes = len(trie)
    valid_states = [i for i in range(num_nodes) if not is_banned[i]]
    if 0 in [i for i in range(num_nodes) if is_banned[i]]:
        return 0

    state_idx = {state: i for i, state in enumerate(valid_states)}
    m = len(valid_states)

    # Precompute step transitions for valid states
    def get_next_state(u: int, c: str) -> int:
        curr = u
        while curr > 0 and c not in trie[curr]:
            curr = fail[curr]
        if c in trie[curr]:
            curr = trie[curr][c]
        else:
            curr = 0
        return curr

    # Transition matrix T: T[i][j] is the number of transitions from state j to state i
    # or T[j][nxt] from j to nxt. Let mat[u][v] = transitions from u to v.
    T = [[0] * m for _ in range(m)]
    for u in valid_states:
        u_idx = state_idx[u]
        for c in alphabet:
            nxt = get_next_state(u, c)
            if not is_banned[nxt]:
                nxt_idx = state_idx[nxt]
                T[u_idx][nxt_idx] += 1

    # Matrix multiplication
    def mat_mul(A: list[list[int]], B: list[list[int]]) -> list[list[int]]:
        size = len(A)
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k] == 0:
                    continue
                for j in range(size):
                    C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % MOD
        return C

    def mat_pow(A: list[list[int]], p: int) -> list[list[int]]:
        size = len(A)
        res = [[1 if i == j else 0 for j in range(size)] for i in range(size)]
        base = A
        while p > 0:
            if p & 1:
                res = mat_mul(res, base)
            base = mat_mul(base, base)
            p >>= 1
        return res

    T_n = mat_pow(T, n)
    start_idx = state_idx[0]

    ans = 0
    for j in range(m):
        ans = (ans + T_n[start_idx][j]) % MOD

    return ans
